import random
from fractions import Fraction

def gaussian_elimination(matrix):
    rows, cols = len(matrix), len(matrix[0])
    for i in range(rows):
        if matrix[i][i] == 0:
            return None  # Singular matrix
        for j in range(i + 1, rows):
            factor = -Fraction(matrix[j][i], matrix[i][i])
            for k in range(cols):
                matrix[j][k] += factor * matrix[i][k]
    rank = sum(1 for row in matrix if any(row))
    return rank

def is_independent(points):
    n = len(points[0])
    A = [[points[j][i] for i in range(n)] for j in range(len(points))]
    rank = gaussian_elimination(A)
    return rank == len(points)

def construct_affine_variety(clauses, num_vars):
    points = []
    for clause in clauses:
        point = [0] * num_vars
        for var in clause:
            if var > 0:
                point[var - 1] += 1
            else:
                point[-var - 1] -= 1
        points.append(point)
    return points

def resolution_length(clauses):
    stack = clauses[:]
    visited = set()
    while stack:
        clause = stack.pop()
        if len(clause) == 0:
            return 1
        literal = random.choice(clause)
        for other_clause in clauses:
            if -literal in other_clause:
                new_clause = [l for l in other_clause if l != -literal]
                if new_clause not in visited:
                    stack.append(new_clause)
                    visited.add(new_clause)
    return 0

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n = random.choice([5, 10, 15, 20, 30, 40])
    num_vars = n
    clauses = []
    for _ in range(n):
